layers.vertex:
attribute vec3 aO; attribute float aT, aK; uniform float uTime; varying vec2 vP; varying float vU, vK;
    void main(){
      float u = uTime - aT, life = aK < .5 ? .16 : .3;
      if (u < 0. || u > life){ gl_Position = vec4(2.,2.,2.,1.); return; }
      vU = u; vK = aK;
      if (aK < .5){
        vec4 mv = viewMatrix*vec4(aO,1.); mv.xyz += normalize(-mv.xyz)*.35;
        float S = .38; mv.xy += position.xy*S; vP = position.xy*S; gl_Position = projectionMatrix*mv;
      } else {
        float S = .5; vP = position.xy*S;
        gl_Position = projectionMatrix*viewMatrix*vec4(aO + vec3(position.x*S, .035, -position.y*S), 1.);
      }
    }

layers.fragment:
uniform vec3 uGold, uOrange; varying vec2 vP; varying float vU, vK; float lcore(float d, float w){ return exp(-(d*d)/(w*w)); }
    void main(){
      vec2 p = vP; float r = length(p), lum = 0., hot = 0.;
      if (vK < .5){
        // single collision flash: a crisp ring that snaps open + a hot centre, gone in 160 ms
        float t = vU/.16, f = pow(1. - t, 1.6);
        float R = .04 + .25*(1. - pow(1. - t, 3.)), w = .007 + .01*(1. - t);
        lum += exp(-pow(abs(r - R)/w, 2.4))*f*.8 + exp(-r*r*240.)*(vU < .033 ? 1.2 : .5*f);
        hot += lcore(r - R, w*.35)*f*.45 + exp(-r*r*700.)*f*.6;
      } else {
        // landing ring on the floor: thin, compact, settles quickly
        float t = vU/.3, f = pow(1. - t, 1.8);
        float R = .08 + .35*(1. - pow(1. - t, 3.)), w = .006 + .015*(1. - t);
        lum += exp(-pow(abs(r - R)/w, 2.4))*f*.5; hot += lcore(r - R, w*.3)*f*.25;
      }
      vec3 outc = mix(uOrange, uGold, .6)*lum + mix(uGold, vec3(1., .96, .88), .6)*hot;
      if (max(outc.r, max(outc.g, outc.b)) < .002) discard;
      gl_FragColor = vec4(outc, 1.);
    }
